<?php
namespace App\Services\Marketing;
use App\Models\{MarketingCampaign,MarketingPost};
use Illuminate\Support\Facades\DB;
class MarketingCampaigns {
 public function query(int $user){return MarketingCampaign::where('merchant_key',app(MarketingPosts::class)->merchant())->where('user_id',$user);}
 public function view(MarketingCampaign $c):array{return ['id'=>$c->id,'name'=>$c->name,'objective'=>$c->objective,'status'=>$c->status,'start'=>$c->starts_on,'end'=>$c->ends_on,'timezone'=>$c->timezone,'url'=>$c->destination_url,'cta'=>$c->cta,'version'=>$c->version,'posts'=>MarketingPost::where('campaign_id',$c->id)->count()];}
 public function listing(int $user):array{return $this->query($user)->latest('updated_at')->get()->map(fn($c)=>$this->view($c))->all();}
 public function save(int $user,array $d,?string $id=null):array{return DB::transaction(function()use($user,$d,$id){$c=$id?$this->query($user)->lockForUpdate()->findOrFail($id):new MarketingCampaign(['merchant_key'=>app(MarketingPosts::class)->merchant(),'user_id'=>$user,'version'=>0]);abort_unless($c->version===$d['version'],409,'This campaign changed. Reload before saving.');$url=parse_url($d['destination_url']);abort_if(isset($url['user'])||isset($url['pass'])||!in_array($url['scheme']??'',['https','http'],true),422,'Choose a valid website address.');$c->fill(['name'=>$d['name'],'objective'=>$d['objective'],'starts_on'=>$d['start'],'ends_on'=>$d['end'],'timezone'=>$d['timezone'],'destination_url'=>$d['destination_url'],'cta'=>$d['cta'],'status'=>$d['status']??$c->status??'Draft','version'=>$c->version+1]);$c->save();return $this->view($c);});}
 public function assign(int $user,string $id,int $version,array $ids):array{return DB::transaction(function()use($user,$id,$version,$ids){$c=$this->query($user)->lockForUpdate()->findOrFail($id);abort_unless($c->version===$version,409,'This campaign changed. Reload before updating its posts.');abort_if($c->status==='Archived',409,'Restore the campaign before changing content.');$all=MarketingPost::where('merchant_key',$c->merchant_key)->where('user_id',$user)->where(function($q)use($id,$ids){$q->where('campaign_id',$id)->orWhereIn('id',$ids);})->orderBy('id')->lockForUpdate()->get();abort_unless(count(array_intersect($all->pluck('id')->all(),$ids))===count($ids),404);foreach($all as $p){$target=in_array($p->id,$ids,true)?$id:null;if($p->campaign_id===$target)continue;abort_if($p->campaign_id&&$p->campaign_id!==$id,409,'This post belongs to another campaign.');abort_unless($p->status==='Draft'&&empty($p->document['delivery_lock'])&&empty($p->document['outcomes']),409,'Only an unpublished draft can change campaign.');$p->forceFill(['campaign_id'=>$target,'version'=>$p->version+1])->save();}$c->increment('version');return $this->view($c->fresh());});}
}
